  const saveBom = () => { if (!selected) return; update.mutate({ id: selected.id, data: { lines: bom.filter(x => x.materialId && Number(x.quantity) > 0).map(x => ({ materialId: Number(x.materialId), quantity: Number(x.quantity) })) } as any }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetProductsQueryKey() }); setSelected(null); } }); };
