function Production() {
  const products = useGetProducts(); const query = useGetProductions(); const check = useCheckProduction(); const create = useCreateProduction(); const qc = useQueryClient(); const [form, setForm] = useState({ productId: "", quantity: "10", date: today() }); const [preview, setPreview] = useState<any>(null);
  const runCheck = () => check.mutate({ data: { productId: Number(form.productId), quantity: Number(form.quantity), date: form.date } as any }, { onSuccess: setPreview });
  const confirm = () => create.mutate({ data: { productId: Number(form.productId), quantity: Number(form.quantity), date: form.date } as any }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetProductionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetProductsQueryKey() }); setPreview(null); } });
  if (products.isLoading || query.isLoading) return <LoadingState />; if (query.isError) return <QueryError retry={() => query.refetch()} />;
  return <div><PageHeader eyebrow="Make / production floor" title="Production" detail="Preview every requirement before you commit a batch to the floor." /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card><SectionTitle title="Plan a batch" detail="Stock is checked before anything is committed." /><div className="grid gap-4"><SelectField label="Product" name="production-product" value={form.productId} onChange={e => { setForm({ ...form, productId: e.target.value }); setPreview(null); }} options={(products.data ?? []).map((x: any) => ({ value: x.id, label: `${x.sku} · ${x.name}` }))} /><Field label="Quantity" name="production-quantity" type="number" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} required /><Field label="Run date" name="production-date" type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} required /><Button onClick={runCheck} disabled={!form.productId || check.isPending} data-testid="button-check-production"><ClipboardList size={15} /> {check.isPending ? "Checking stock…" : "Check requirements"}</Button></div>{preview && <div className={`mt-5 rounded-xl border p-4 ${preview.canProduce ? "border-[#b9dbc6] bg-[#edf8f0]" : "border-[#e9c5a7] bg-[#fff6e9]"}`} data-testid="production-preview"><div className="flex items-start gap-3">{preview.canProduce ? <Check className="mt-0.5 text-[#347a54]" size={18} /> : <AlertTriangle className="mt-0.5 text-[#a26519]" size={18} />}<div><p className="font-bold">{preview.canProduce ? "Ready to produce" : "Shortage found"}</p><p className="mt-1 text-xs text-muted-foreground">{preview.productName} · {number(preview.quantity)} units · est. unit cost {money(preview.estimatedUnitCost)}</p></div></div><div className="mt-4 grid gap-2">{(preview.requirements ?? []).map((x: any) => <div className="flex items-center justify-between text-xs" key={x.materialId}><span>{x.materialName}</span><span className="font-mono">{number(x.available)} / {number(x.required)} {x.unit} {x.shortage > 0 && <b className="ml-2 text-destructive">−{number(x.shortage)}</b>}</span></div>)}</div>{preview.canProduce && <Button className="mt-4 w-full" onClick={confirm} disabled={create.isPending} data-testid="button-confirm-production">{create.isPending ? "Confirming…" : "Confirm production run"}</Button>}</div>}</Card><Card><SectionTitle title="Run history" detail={`${(query.data ?? []).length} completed batches`} />{(query.data ?? []).length === 0 ? <EmptyState title="No production runs yet" detail="Your first confirmed batch will leave a trace here." /> : <div className="divide-y divide-border">{(query.data ?? []).map((x: any) => <div className="flex items-center gap-4 py-3 first:pt-0 last:pb-0" key={x.id} data-testid={`row-production-${x.id}`}><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-secondary text-primary"><Factory size={16} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{x.productName}</p><p className="mt-1 text-xs text-muted-foreground">{dateLabel(x.date)} · {number(x.quantity)} units</p></div><div className="text-right"><p className="font-mono text-sm">{money(x.totalCost)}</p><p className="mt-1 text-[11px] text-muted-foreground">total cost</p></div><div className="ml-2"><StatusPill tone={x.status === "completed" ? "good" : "neutral"}>{x.status ?? "completed"}</StatusPill>{x.status === "completed" && <button className="mt-2 text-xs font-bold text-destructive hover:underline" onClick={() => void cancelTransaction("production", x.id, () => { qc.invalidateQueries({ queryKey: getGetProductionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetProductsQueryKey() }); })}>Cancel</button>}</div></div>)}</div>}</Card></div></div>;
}

