function Sales() {
  const query = useGetSales(); const products = useGetProducts(); const customers = useGetCustomers(); const create = useCreateSale(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ customerId: "", productId: "", quantity: "1", sellingPrice: "", paymentMethod: "cash", paidAmount: "0", date: today() });
  const selected = (products.data ?? []).find((x: any) => String(x.id) === form.productId) as any; const submit = (e: FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, customerId: Number(form.customerId), productId: Number(form.productId), quantity: Number(form.quantity), sellingPrice: form.sellingPrice ? Number(form.sellingPrice) : undefined, paidAmount: Number(form.paidAmount) } as any }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetSalesQueryKey() }); qc.invalidateQueries({ queryKey: getGetCustomersQueryKey() }); qc.invalidateQueries({ queryKey: getGetProductsQueryKey() }); setShow(false); } }); };
  if (query.isLoading || products.isLoading || customers.isLoading) return <LoadingState />; if (query.isError) return <QueryError retry={() => query.refetch()} />; const list = query.data ?? [];
  return <div><PageHeader eyebrow="Sell / order book" title="Sales" detail="Turn finished stock into a clean record of revenue, margin, and money collected." action={<Button onClick={() => setShow(!show)} data-testid="button-add-sale"><Plus size={16} /> Record sale</Button>} />{show && <Card className="mb-5 border-accent/50 bg-secondary/40"><SectionTitle title="Record a sale" action={<button onClick={() => setShow(false)} data-testid="button-cancel-sale"><X size={17} /></button>} /><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><SelectField label="Customer" name="sale-customer" value={form.customerId} onChange={e => setForm({ ...form, customerId: e.target.value })} options={(customers.data ?? []).map((x: any) => ({ value: x.id, label: x.name }))} /><SelectField label="Product" name="sale-product" value={form.productId} onChange={e => { const product = (products.data ?? []).find((x: any) => String(x.id) === e.target.value) as any; setForm({ ...form, productId: e.target.value, sellingPrice: product ? String(product.sellingPrice) : "" }); }} options={(products.data ?? []).map((x: any) => ({ value: x.id, label: `${x.sku} · ${x.name}` }))} /><Field label="Quantity" name="sale-quantity" type="number" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} required /><Field label="Selling price / unit" name="sale-price" type="number" step="0.01" value={form.sellingPrice} onChange={e => setForm({ ...form, sellingPrice: e.target.value })} /><SelectField label="Payment method" name="sale-payment-method" value={form.paymentMethod} onChange={e => setForm({ ...form, paymentMethod: e.target.value })} options={[{ value: "cash", label: "Cash" }, { value: "credit", label: "Credit" }, { value: "partial", label: "Partial" }]} /><Field label="Paid amount" name="sale-paid" type="number" step="0.01" value={form.paidAmount} onChange={e => setForm({ ...form, paidAmount: e.target.value })} /><Field label="Sale date" name="sale-date" type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /><div className="flex items-end"><Button disabled={create.isPending || !selected} data-testid="button-save-sale">Save sale</Button></div></form></Card>}<HistoryTable title="Sales history" columns={["Date", "Customer", "Product", "Revenue", "Gross profit", "Balance"]} rows={list.map((x: any) => [dateLabel(x.date), x.customerName, `${x.productName} × ${number(x.quantity)}`, money(x.revenue), <span className="text-[#347a54]">{money(x.grossProfit)}</span>, money(x.balanceDue)])} ids={list.map((x: any) => x.id)} statuses={list.map((x: any) => x.status)} cancelPath="sales" onChanged={() => { qc.invalidateQueries({ queryKey: getGetSalesQueryKey() }); qc.invalidateQueries({ queryKey: getGetCustomersQueryKey() }); qc.invalidateQueries({ queryKey: getGetProductsQueryKey() }); }} empty="No sales recorded yet." /></div>;
}

function Payments() {
  const payments = useGetPayments();
  const customers = useGetCustomers(); const create = useCreatePayment(); const qc = useQueryClient(); const [form, setForm] = useState({ customerId: "", amount: "", method: "cash", date: today(), notes: "" }); const submit = (e: FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, customerId: Number(form.customerId), amount: Number(form.amount) } as any }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetCustomersQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setForm({ ...form, amount: "", notes: "" }); } }); };
  if (customers.isLoading || payments.isLoading) return <LoadingState />; if (customers.isError || payments.isError) return <QueryError retry={() => { void customers.refetch(); void payments.refetch(); }} />;
  return <div><PageHeader eyebrow="Sell / money in" title="Payments" detail="Apply customer payments and preserve a clear, reversible payment history." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card><SectionTitle title="Record customer payment" detail="Balances update when the payment is saved." /><form onSubmit={submit} className="grid gap-4"><SelectField label="Customer" name="payment-customer" value={form.customerId} onChange={e => setForm({ ...form, customerId: e.target.value })} options={(customers.data ?? []).filter((x: any) => x.outstandingBalance > 0).map((x: any) => ({ value: x.id, label: `${x.name} · ${money(x.outstandingBalance)} due` }))} /><Field label="Amount" name="payment-amount" type="number" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} required /><SelectField label="Method" name="payment-method" value={form.method} onChange={e => setForm({ ...form, method: e.target.value })} options={[{ value: "cash", label: "Cash" }, { value: "bank", label: "Bank transfer" }, { value: "card", label: "Card" }]} /><Field label="Date" name="payment-date" type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /><Field label="Note" name="payment-notes" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /><Button disabled={create.isPending || !form.customerId}><Wallet size={15} /> Save payment</Button></form></Card><HistoryTable title="Payment history" columns={["ID", "Date", "Customer", "Amount"]} rows={(payments.data ?? []).map((x: any) => [`#${x.id}`, dateLabel(x.date), x.customerName, money(x.amount)])} ids={(payments.data ?? []).map((x: any) => x.id)} statuses={(payments.data ?? []).map((x: any) => x.status)} cancelPath="payments" onChanged={() => { qc.invalidateQueries({ queryKey: getGetPaymentsQueryKey() }); qc.invalidateQueries({ queryKey: getGetCustomersQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); }} empty="No payments recorded yet." /></div></div>;
  return <div><PageHeader eyebrow="Sell / money in" title="Payments" detail="Apply customer payments with a small, auditable note of what arrived." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card><SectionTitle title="Record customer payment" detail="Balances update when the payment is saved." /><form onSubmit={submit} className="grid gap-4"><SelectField label="Customer" name="payment-customer" value={form.customerId} onChange={e => setForm({ ...form, customerId: e.target.value })} options={(customers.data ?? []).filter((x: any) => x.outstandingBalance > 0).map((x: any) => ({ value: x.id, label: `${x.name} · ${money(x.outstandingBalance)} due` }))} /><Field label="Amount" name="payment-amount" type="number" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} required /><SelectField label="Method" name="payment-method" value={form.method} onChange={e => setForm({ ...form, method: e.target.value })} options={[{ value: "cash", label: "Cash" }, { value: "bank", label: "Bank transfer" }, { value: "card", label: "Card" }]} /><Field label="Date" name="payment-date" type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /><Field label="Note" name="payment-notes" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Optional reference" /><Button disabled={create.isPending || !form.customerId} data-testid="button-save-payment"><Wallet size={15} /> {create.isPending ? "Saving…" : "Save payment"}</Button>{create.isSuccess && <p className="text-sm font-semibold text-[#347a54]" data-testid="status-payment-success">Payment recorded and balance updated.</p>}</form></Card><Card><SectionTitle title="Balances to collect" detail="Customers with open receivables" />{(customers.data ?? []).filter((x: any) => x.outstandingBalance > 0).length === 0 ? <EmptyState title="Everyone is settled" detail="No customer payments are waiting in the queue." /> : <div className="divide-y divide-border">{(customers.data ?? []).filter((x: any) => x.outstandingBalance > 0).map((x: any) => <div className="flex items-center justify-between py-3 first:pt-0" key={x.id} data-testid={`balance-customer-${x.id}`}><div><p className="font-bold">{x.name}</p><p className="mt-1 text-xs text-muted-foreground">{x.phone || "Contact not set"}</p></div><p className="font-mono text-sm text-[#91433b]">{money(x.outstandingBalance)}</p></div>)}</div>}</Card></div></div>;
}

function Expenses() {
  const query = useGetExpenses(); const create = useCreateExpense(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ category: "Shipping", amount: "", date: today(), paymentMethod: "bank", description: "" }); const submit = (e: FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, amount: Number(form.amount) } as any }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetExpensesQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setShow(false); } }); };
  if (query.isLoading) return <LoadingState />; if (query.isError) return <QueryError retry={() => query.refetch()} />; const list = query.data ?? [];
  return <div><PageHeader eyebrow="Finance / overhead" title="Expenses" detail="Capture the cost of running the studio, not just the cost of making a bottle." action={<Button onClick={() => setShow(!show)} data-testid="button-add-expense"><Plus size={16} /> Log expense</Button>} />{show && <Card className="mb-5 bg-secondary/40"><SectionTitle title="Log operating expense" action={<button onClick={() => setShow(false)} data-testid="button-cancel-expense"><X size={17} /></button>} /><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><Field label="Category" name="expense-category" value={form.category} onChange={e => setForm({ ...form, category: e.target.value })} required /><Field label="Amount" name="expense-amount" type="number" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} required /><Field label="Date" name="expense-date" type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} required /><SelectField label="Payment method" name="expense-method" value={form.paymentMethod} onChange={e => setForm({ ...form, paymentMethod: e.target.value })} options={[{ value: "bank", label: "Bank transfer" }, { value: "cash", label: "Cash" }, { value: "card", label: "Card" }]} /><div className="flex items-end"><Button disabled={create.isPending} data-testid="button-save-expense">Save expense</Button></div><div className="sm:col-span-2 lg:col-span-5"><Field label="Description" name="expense-description" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="What was this for?" /></div></form></Card>}<HistoryTable title="Expense history" columns={["Date", "Category", "Description", "Method", "Amount"]} rows={list.map((x: any) => [dateLabel(x.date), x.category, x.description || "—", x.paymentMethod, money(x.amount)])} ids={list.map((x: any) => x.id)} statuses={list.map((x: any) => x.status)} cancelPath="expenses" onChanged={() => { qc.invalidateQueries({ queryKey: getGetExpensesQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); }} empty="No expenses recorded yet." /></div>;
}

function StockLedger() {
  const [search, setSearch] = useState(""); const query = useGetStockLedger(search ? { search } : undefined); if (query.isLoading) return <LoadingState />; if (query.isError) return <QueryError retry={() => query.refetch()} />; const list = query.data ?? [];
  return <div><PageHeader eyebrow="Finance / audit trail" title="Stock ledger" detail="Every movement in and out, in one place. Search by item or movement type." /><Card className="overflow-hidden p-0"><div className="flex flex-col gap-3 border-b border-border p-5 sm:flex-row sm:items-center sm:justify-between"><SectionTitle title="Movement ledger" detail={`${list.length} movements`} /><label className="flex items-center gap-2 rounded-xl bg-secondary px-3 py-2 text-xs text-muted-foreground"><Search size={14} /><input data-testid="input-search-ledger" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search ledger" className="w-36 bg-transparent outline-none" /></label></div>{list.length === 0 ? <div className="p-5"><EmptyState title="No stock movements yet" detail="Purchases, production, and sales will build your audit trail here." /></div> : <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-secondary/55 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><tr><th className="px-5 py-3">Date</th><th className="px-5 py-3">Item</th><th className="px-5 py-3">Movement</th><th className="px-5 py-3">In</th><th className="px-5 py-3">Out</th><th className="px-5 py-3">Reference</th></tr></thead><tbody className="divide-y divide-border">{list.map((x: any) => <tr key={x.id} className="hover:bg-secondary/30" data-testid={`row-ledger-${x.id}`}><td className="px-5 py-4 text-muted-foreground">{dateLabel(x.date)}</td><td className="px-5 py-4 font-bold">{x.itemName}<small className="ml-2 text-xs font-normal text-muted-foreground">{x.unit}</small></td><td className="px-5 py-4"><StatusPill tone={x.quantityIn > 0 ? "good" : "neutral"}>{x.transactionType}</StatusPill></td><td className="px-5 py-4 font-mono text-[#347a54]">{x.quantityIn ? `+${number(x.quantityIn)}` : "—"}</td><td className="px-5 py-4 font-mono text-[#91433b]">{x.quantityOut ? `−${number(x.quantityOut)}` : "—"}</td><td className="px-5 py-4 font-mono text-xs text-muted-foreground">#{x.referenceId}</td></tr>)}</tbody></table></div>}</Card></div>;
}

function Reports() {
  const query = useGetProfitLoss(); if (query.isLoading) return <LoadingState />; if (query.isError) return <QueryError retry={() => query.refetch()} />; const data: any = query.data;
  return <div><PageHeader eyebrow="Finance / reporting" title="Reports" detail="A clear read on the business: what came in, what it cost, and what remains." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ label: "Revenue", value: money(data?.revenue), icon: ArrowUpRight, tone: "good" }, { label: "Cost of goods", value: money(data?.cogs), icon: ArrowDownLeft, tone: "warn" }, { label: "Gross profit", value: money(data?.grossProfit), icon: BarChart3, tone: "accent" }, { label: "Net profit", value: money(data?.netProfit), icon: CircleDollarSign, tone: "green" }].map(({ label, value, icon: Icon, tone }) => <Card key={label} data-testid={`report-card-${label.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-start justify-between"><p className="text-xs font-semibold text-muted-foreground">{label}</p><Icon size={16} className={tone === "warn" ? "text-[#a26519]" : tone === "accent" ? "text-primary" : "text-[#347a54]"} /></div><p className="mt-5 font-mono text-2xl">{value}</p></Card>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><Card><SectionTitle title="Profit and loss" detail={`${data?.from ? dateLabel(data.from) : "Current period"} — ${data?.to ? dateLabel(data.to) : "Today"}`} /><div className="grid gap-5">{[{ label: "Revenue", value: data?.revenue, color: "bg-primary" }, { label: "COGS", value: data?.cogs, color: "bg-[#c99c58]" }, { label: "Expenses", value: data?.expenses, color: "bg-[#c8796f]" }, { label: "Net profit", value: data?.netProfit, color: "bg-[#4b9b76]" }].map(({ label, value, color }) => { const max = Math.max(Number(data?.revenue) || 1, Number(data?.cogs) || 0, Number(data?.expenses) || 0); return <div key={label} data-testid={`report-row-${label.toLowerCase().replace(" ", "-")}`}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{label}</span><span className="font-mono">{money(value)}</span></div><div className="h-3 rounded-full bg-secondary"><div className={`h-3 rounded-full ${color}`} style={{ width: `${Math.max(3, ((Number(value) || 0) / max) * 100)}%` }} /></div></div>; })}</div></Card><Card className="bg-primary text-primary-foreground"><SectionTitle title="Margins" detail="The useful percentage view" /><div className="mt-6 grid gap-7"><div><p className="text-xs text-primary-foreground/60">Gross margin</p><p className="mt-1 font-mono text-4xl">{number(data?.grossMargin)}%</p></div><div><p className="text-xs text-primary-foreground/60">Net margin</p><p className="mt-1 font-mono text-4xl">{number(data?.netMargin)}%</p></div><div className="border-t border-primary-foreground/15 pt-4 text-xs text-primary-foreground/60">Margins reflect recorded sales, purchases, and operating expenses for the selected period.</div></div></Card></div></div>;
}

function AppRouter() {
  return <ErrorBoundary><Shell><Switch><Route path="/" component={Dashboard} /><Route path="/materials" component={Materials} /><Route path="/suppliers" component={Suppliers} /><Route path="/purchases" component={Purchases} /><Route path="/products" component={Products} /><Route path="/production" component={Production} /><Route path="/customers" component={Customers} /><Route path="/sales" component={Sales} /><Route path="/payments" component={Payments} /><Route path="/expenses" component={Expenses} /><Route path="/stock-ledger" component={StockLedger} /><Route path="/reports" component={Reports} /><Route><div className="py-20 text-center"><FileText className="mx-auto text-muted-foreground" size={28} /><h1 className="mt-4 text-2xl font-extrabold">Page not found</h1><Link href="/" className="mt-4 inline-block font-bold text-primary hover:underline" data-testid="link-back-overview">Back to overview</Link></div></Route></Switch></Shell></ErrorBoundary>;
}

export default function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}